// The remote's stock icon set (ids 1..N, shared with the compiler and the remote firmware).
// Source of truth: harmony_addon/frontend-shared/icons.json, generated by tools/gen_icons.py.
import data from '@shared/icons.json';

export interface StockIcon {
  id: number;
  name: string;
  keywords: string[];
  /** inner SVG markup for a 24x24 viewBox, stroke-based (currentColor) */
  svg: string;
}

export const GLYPH_BASE: number = data.glyph_base;
export const STOCK_ICONS: readonly StockIcon[] = data.icons;

const byId = new Map(STOCK_ICONS.map((i) => [i.id, i]));
const byName = new Map(STOCK_ICONS.map((i) => [i.name, i]));

export const stockIconById = (id: number): StockIcon | undefined => byId.get(id);
export const stockIconByName = (name: string): StockIcon | undefined => byName.get(name);
/** The wire id for a config `icon:` name; `none` and unknown names are 0 (no icon). */
export const stockIconId = (name: string): number => byName.get(name)?.id ?? 0;
/** The remote's private-use glyph for an icon id (what its icon font renders). */
export const glyphFor = (id: number): string => String.fromCodePoint(GLYPH_BASE + id);
